#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <cstring>
#include <unordered_map>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <chrono>
#include <mutex>

static const unsigned char HMAC_KEY[] = "s3cr3t_k3y_f0r_s1gn1ng_2024";
static const size_t HMAC_KEY_LEN = sizeof(HMAC_KEY) - 1;

struct SerializedObject {
    uint32_t version;
    uint32_t payload_len;
    uint64_t timestamp;
    unsigned char signature[32];
    std::vector<unsigned char> payload;
};

class SignatureCache {
private:
    std::unordered_map<std::string, uint64_t> seen_signatures_;
    std::mutex mtx_;
    static const uint64_t WINDOW_SIZE_MS = 300000; // 5 minute window

public:
    bool check_and_record(const unsigned char* sig, uint64_t timestamp) {
        std::lock_guard<std::mutex> lock(mtx_);
        std::string sig_hex(reinterpret_cast<const char*>(sig), 32);

        auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        // Evict old entries
        for (auto it = seen_signatures_.begin(); it != seen_signatures_.end();) {
            if (now - it->second > WINDOW_SIZE_MS) {
                it = seen_signatures_.erase(it);
            } else {
                ++it;
            }
        }

        // Check if signature was seen before
        if (seen_signatures_.find(sig_hex) != seen_signatures_.end()) {
            return false; // replay detected
        }

        seen_signatures_[sig_hex] = timestamp;
        return true;
    }
};

class ObjectDeserializer {
private:
    SignatureCache cache_;

    bool verify_signature(const SerializedObject& obj) {
        unsigned char computed[32];
        unsigned int len = 0;

        // Build signing buffer: version + payload_len + timestamp + payload
        size_t buf_size = sizeof(obj.version) + sizeof(obj.payload_len) + 
                         sizeof(obj.timestamp) + obj.payload.size();
        std::vector<unsigned char> sign_buf(buf_size);

        size_t offset = 0;
        memcpy(sign_buf.data() + offset, &obj.version, sizeof(obj.version));
        offset += sizeof(obj.version);
        memcpy(sign_buf.data() + offset, &obj.payload_len, sizeof(obj.payload_len));
        offset += sizeof(obj.payload_len);
        memcpy(sign_buf.data() + offset, &obj.timestamp, sizeof(obj.timestamp));
        offset += sizeof(obj.timestamp);
        memcpy(sign_buf.data() + offset, obj.payload.data(), obj.payload.size());

        HMAC(EVP_sha256(), HMAC_KEY, HMAC_KEY_LEN,
             sign_buf.data(), sign_buf.size(), computed, &len);

        return memcmp(computed, obj.signature, 32) == 0;
    }

    bool check_timestamp_freshness(uint64_t timestamp) {
        auto now = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        uint64_t now_ms = static_cast<uint64_t>(now);

        // Allow 5 minute clock skew
        if (timestamp > now_ms + 300000) return false;
        if (now_ms > timestamp + 300000) return false;
        return true;
    }

public:
    bool process_upload(const std::vector<unsigned char>& raw_data) {
        if (raw_data.size() < sizeof(uint32_t) * 2 + sizeof(uint64_t) + 32) {
            std::cerr << "Upload too small" << std::endl;
            return false;
        }

        SerializedObject obj;
        size_t offset = 0;

        memcpy(&obj.version, raw_data.data() + offset, sizeof(obj.version));
        offset += sizeof(obj.version);

        memcpy(&obj.payload_len, raw_data.data() + offset, sizeof(obj.payload_len));
        offset += sizeof(obj.payload_len);

        memcpy(&obj.timestamp, raw_data.data() + offset, sizeof(obj.timestamp));
        offset += sizeof(obj.timestamp);

        memcpy(obj.signature, raw_data.data() + offset, 32);
        offset += 32;

        if (obj.payload_len > raw_data.size() - offset) {
            std::cerr << "Invalid payload length" << std::endl;
            return false;
        }

        obj.payload.assign(raw_data.data() + offset, 
                          raw_data.data() + offset + obj.payload_len);

        // Step 1: Verify cryptographic signature
        if (!verify_signature(obj)) {
            std::cerr << "Signature verification failed" << std::endl;
            return false;
        }

        // Step 2: Check timestamp freshness
        if (!check_timestamp_freshness(obj.timestamp)) {
            std::cerr << "Timestamp outside acceptable window" << std::endl;
            return false;
        }

        // Step 3: Check replay cache
        if (!cache_.check_and_record(obj.signature, obj.timestamp)) {
            std::cerr << "Replay detected" << std::endl;
            return false;
        }

        // Process the deserialized object
        std::cout << "Processing object v" << obj.version 
                  << " with " << obj.payload_len << " bytes" << std::endl;
        return true;
    }
};

int main() {
    ObjectDeserializer deserializer;

    std::ifstream file("upload.bin", std::ios::binary);
    if (!file) {
        std::cerr << "Cannot open upload file" << std::endl;
        return 1;
    }

    std::vector<unsigned char> data((std::istreambuf_iterator<char>(file)),
                                     std::istreambuf_iterator<char>());
    file.close();

    if (deserializer.process_upload(data)) {
        std::cout << "Upload processed successfully" << std::endl;
    }

    return 0;
}
